      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill$t$
     AND m.title = $u$Unidad 1. Biología del cáncer y bases de la farmacología antineoplásica$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill$t$, $u$Unidad 1. Biología del cáncer y bases de la farmacología antineoplásica$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un adulto mayor acumula medicamentos que ya no tienen indicación vigente. Lo que está en juego es el criterio de ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill con tus propias palabras y reconocer por qué importa en curso de Farmacología Oncológica.","Relacionar ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill con unidad 1. Biología del cáncer y bases de la farmacología antineoplásica y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta cómo el ciclo celular y la cinética de crecimiento tumoral determinan la eficacia y el esquema de los antineoplásicos."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill aparece en medio de una decisión que no admite improvisación: un adulto mayor acumula medicamentos que ya no tienen indicación vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Biología del cáncer y bases de la farmacología antineoplásica. El objetivo del curso es claro: Desarrollar en el Químico Farmacéutico las bases farmacológicas, técnicas y normativas para participar en la atención del paciente oncológico en Colombia: validar prescripciones, prevenir y manejar toxicidades, garantizar el manejo seguro de medicamentos peligrosos, gestionar el acceso y realizar farmacovigilancia. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta cómo el ciclo celular y la cinética de crecimiento tumoral determinan la eficacia y el esquema de los antineoplásicos.","Una pregunta que se usa para comprobar esta clase es: «¿Qué plantea la hipótesis de muerte logarítmica (log-kill) de los citotóxicos?» La respuesta correcta se apoya en lo siguiente: Según la hipótesis log-kill, cada ciclo de quimioterapia elimina una fracción constante de las células tumorales, no un número fijo; por eso se necesitan varios ciclos y la intensidad de dosis importa. Los tumores con alta fracción de crecimiento son más sensibles a los citotóxicos. La fuente citada es: Fundamentos de farmacología antineoplásica.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Biología del cáncer y bases de la farmacología antineoplásica y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de primera consulta con comunicación al oncólogo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Explica qué implica el cambio de peso para la superficie corporal y la dosis. Evidencia que debe quedar: Registro del paso.","Revisa los datos de laboratorio que necesitas para validar (función renal y hepática, hemograma). Evidencia que debe quedar: Registro del paso.","Concilia la medicación crónica e identifica interacciones relevantes (por ejemplo, con la warfarina). Evidencia que debe quedar: Registro del paso.","Analiza el suplemento herbal y qué harías con él. Evidencia que debe quedar: Registro del paso.","Prepara la educación sobre los efectos esperados y los signos de alarma. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al oncólogo con tus hallazgos. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Error: monitorizar sin umbral de acción Corrección: pedir un examen sin saber qué se hará con el resultado no es seguimiento.","Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill»?","respuesta":"Interpreta cómo el ciclo celular y la cinética de crecimiento tumoral determinan la eficacia y el esquema de los antineoplásicos."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de primera consulta con comunicación al oncólogo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Biología del cáncer y bases de la farmacología antineoplásica.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"CICLO CELULAR. Resumen. Fases: G0, G1, S, G2. Puntos de Control del Ciclo Celular","url":"https://www.youtube.com/watch?v=M-3GKnuD4_I"},{"cita":"¿Qué es la Quimioterapia?","url":"https://www.youtube.com/watch?v=rsOeSFyS9jc"},{"cita":"Farmacología de los antineoplásicos (temas 38–39, curso de Farmacología). Universidad de Alcalá (ES)","url":"https://farmamol.web.uah.es/PDF_files/Farma_3MG_T38-39-2021-22.pdf"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill"}],"keywords":["curso","farmacología","oncológica","ciclo","celular","cinética","tumoral","fracción","crecimiento","gompertziano","unidad","biología"],"mapa":{"centro":"Ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 1. Biología del cáncer y bases de la farmacología antineoplásica","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se aplica: Primera consulta farmacéutica de un paciente oncológico","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Explica qué implica el cambio de peso para la superficie corporal y la dosis.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Revisa los datos de laboratorio que necesitas para validar (función renal y hepática, hemograma).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Concilia la medicación crónica e identifica interacciones relevantes (por ejemplo, con la warfarina).","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza el suplemento herbal y qué harías con él.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Prepara la educación sobre los efectos esperados y los signos de alarma.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta la comunicación al oncólogo con tus hallazgos.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Ciclo celular y cinética tumoral: fracción de crecimiento, crecimiento gompertziano y log-kill","contexto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, el equipo analiza este caso de unidad 1. Biología del cáncer y bases de la farmacología antineoplásica: Don Alberto tiene 62 años, vive en Bogotá y fue operado de un adenocarcinoma de colon estadio III (datos simulados). El oncólogo prescribe quimioterapia adyuvante con capecitabina y oxaliplatino. Tiene hipertensión con losartán, diabetes con metformina, toma warfarina por una trombosis previa y un suplemento «para las defensas» con hierbas. El peso registrado en la orden es de 78 kg, pero hoy pesa 70 kg. La pregunta que decide esta clase es: ¿Qué plantea la hipótesis de muerte logarítmica (log-kill) de los citotóxicos?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Que cada ciclo elimina un número fijo de células tumorales, sin importar el tamaño del tumor.","correcta":false,"retro":"La hipótesis habla de una fracción, no de un número fijo."},{"texto":"Que la primera dosis de quimioterapia elimina todas las células tumorales sensibles que hay en el cuerpo.","correcta":false,"retro":"Si fuera así no se necesitarían varios ciclos."},{"texto":"Que cada ciclo elimina una fracción constante de las células; por eso se necesitan varios ciclos.","correcta":true,"retro":"Correcto. Una fracción fija deja células residuales."},{"texto":"Que el efecto de la quimioterapia aumenta a medida que el tumor crece y tiene más células.","correcta":false,"retro":"Los tumores grandes suelen tener menor fracción de crecimiento."}]}}$j$::jsonb;
