  -- 10. Privación androgénica: agonistas y antagonistas de GnRH
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Privación androgénica: agonistas y antagonistas de GnRH$t$
     AND m.title = $u$Unidad 2. Terapia hormonal en oncología$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Privación androgénica: agonistas y antagonistas de GnRH$t$, $u$Unidad 2. Terapia hormonal en oncología$u$;
