    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 13. Introducción a la unidad: toxicidades frecuentes y terapia de soporte
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción a la unidad: toxicidades frecuentes y terapia de soporte$t$
     AND m.title = $u$Unidad 3. Tratamiento de soporte en el paciente oncológico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción a la unidad: toxicidades frecuentes y terapia de soporte$t$, $u$Unidad 3. Tratamiento de soporte en el paciente oncológico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción a la unidad: toxicidades frecuentes y terapia de soporte","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un paciente con enfermedad renal recibe una dosis que no fue ajustada. Lo que está en juego es el criterio de introducción a la unidad: toxicidades frecuentes y terapia de soporte. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción a la unidad: toxicidades frecuentes y terapia de soporte con tus propias palabras y reconocer por qué importa en curso de Farmacología Oncológica.","Relacionar introducción a la unidad: toxicidades frecuentes y terapia de soporte con unidad 3. Tratamiento de soporte en el paciente oncológico y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción a la unidad: toxicidades frecuentes y terapia de soporte y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Resume las principales toxicidades de los antineoplásicos y el papel de la terapia de soporte en la calidad de vida y la adherencia."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, introducción a la unidad: toxicidades frecuentes y terapia de soporte aparece en medio de una decisión que no admite improvisación: un paciente con enfermedad renal recibe una dosis que no fue ajustada. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Tratamiento de soporte en el paciente oncológico. El objetivo del curso es claro: Desarrollar en el Químico Farmacéutico las bases farmacológicas, técnicas y normativas para participar en la atención del paciente oncológico en Colombia: validar prescripciones, prevenir y manejar toxicidades, garantizar el manejo seguro de medicamentos peligrosos, gestionar el acceso y realizar farmacovigilancia. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Resume las principales toxicidades de los antineoplásicos y el papel de la terapia de soporte en la calidad de vida y la adherencia.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en indicación y en problema relacionado con medicamentos, no en la intuición.","La clase pertenece a unidad 3. Tratamiento de soporte en el paciente oncológico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción a la unidad: toxicidades frecuentes y terapia de soporte, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Confirmar la indicación. Verifica el problema de salud, el objetivo terapéutico y si el medicamento sigue siendo necesario. Evidencia que debe quedar: Problema de salud documentado.","Evaluar al paciente. Revisa edad, función renal y hepática, embarazo, comorbilidades y medicación concomitante. Evidencia que debe quedar: Perfil farmacoterapéutico.","Revisar seguridad e interacciones. Busca contraindicaciones, duplicidades, interacciones y riesgos de toxicidad. Evidencia que debe quedar: Lista de riesgos priorizada.","Ajustar y monitorizar. Propone dosis y parámetros de seguimiento, con frecuencia y umbral de acción. Evidencia que debe quedar: Plan de monitorización.","Educar y documentar. Explica el plan al paciente y registra la intervención, la respuesta y el seguimiento. Evidencia que debe quedar: Nota de seguimiento.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En una unidad de oncología, una encuesta muestra que el 40 % de los pacientes tiene dolor moderado o intenso (datos simulados). Muchos reciben solo tramadol, algunos no consiguen morfina por trámites de control especial y otros temen «volverse adictos». No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: ignorar la automedicación Corrección: los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento.","Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Error: monitorizar sin umbral de acción Corrección: pedir un examen sin saber qué se hará con el resultado no es seguimiento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción a la unidad: toxicidades frecuentes y terapia de soporte en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción a la unidad: toxicidades frecuentes y terapia de soporte»?","respuesta":"Resume las principales toxicidades de los antineoplásicos y el papel de la terapia de soporte en la calidad de vida y la adherencia."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Introducción a la unidad: toxicidades frecuentes y terapia de soporte se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Tratamiento de soporte en el paciente oncológico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"Efectos gastrointestinales por quimioterapia","url":"https://www.youtube.com/watch?v=aXuwZ1mykl4"},{"cita":"[Página web] MASCC Guidelines – índice de guías de soporte (antieméticos, mucositis, neutropenia). MASCC (EN)","url":"https://mascc.org/resources/mascc-guidelines/"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción a la unidad: toxicidades frecuentes y terapia de soporte en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de introducción a la unidad: toxicidades frecuentes y terapia de soporte"}],"keywords":["curso","farmacología","oncológica","introducción","unidad","toxicidades","frecuentes","terapia","soporte","tratamiento","paciente","oncológico"],"mapa":{"centro":"Introducción a la unidad: toxicidades frecuentes y terapia de soporte","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 3. Tratamiento de soporte en el paciente oncológico","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Confirmar la indicación","Evaluar al paciente","Revisar seguridad e interacciones"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Problema de salud documentado","Perfil farmacoterapéutico","Lista de riesgos priorizada"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se razona una decisión farmacoterapéutica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Confirmar la indicación","detalle":"Verifica el problema de salud, el objetivo terapéutico y si el medicamento sigue siendo necesario.","icono":"Search","evidencia":"Problema de salud documentado"},{"titulo":"Evaluar al paciente","detalle":"Revisa edad, función renal y hepática, embarazo, comorbilidades y medicación concomitante.","icono":"ClipboardList","evidencia":"Perfil farmacoterapéutico"},{"titulo":"Revisar seguridad e interacciones","detalle":"Busca contraindicaciones, duplicidades, interacciones y riesgos de toxicidad.","icono":"Workflow","evidencia":"Lista de riesgos priorizada"},{"titulo":"Ajustar y monitorizar","detalle":"Propone dosis y parámetros de seguimiento, con frecuencia y umbral de acción.","icono":"FileCheck","evidencia":"Plan de monitorización"},{"titulo":"Educar y documentar","detalle":"Explica el plan al paciente y registra la intervención, la respuesta y el seguimiento.","icono":"RefreshCw","evidencia":"Nota de seguimiento"}]},"caso":{"titulo":"Introducción a la unidad: toxicidades frecuentes y terapia de soporte","contexto":"En una unidad de oncología, una encuesta muestra que el 40 % de los pacientes tiene dolor moderado o intenso (datos simulados). Muchos reciben solo tramadol, algunos no consiguen morfina por trámites de control especial y otros temen «volverse adictos».","pregunta":"¿Qué decisión demuestra que entendiste introducción a la unidad: toxicidades frecuentes y terapia de soporte?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
