    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 14. Fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO$t$
     AND m.title = $u$Unidad 3. Tratamiento de soporte en el paciente oncológico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO$t$, $u$Unidad 3. Tratamiento de soporte en el paciente oncológico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un adulto mayor acumula medicamentos que ya no tienen indicación vigente. Lo que está en juego es el criterio de fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO con tus propias palabras y reconocer por qué importa en curso de Farmacología Oncológica.","Relacionar fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO con unidad 3. Tratamiento de soporte en el paciente oncológico y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta los tipos de NVIQ (aguda, tardía, anticipatoria, irruptiva) y la clasificación actualizada de riesgo emetógeno MASCC/ESMO."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO aparece en medio de una decisión que no admite improvisación: un adulto mayor acumula medicamentos que ya no tienen indicación vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Tratamiento de soporte en el paciente oncológico. El objetivo del curso es claro: Desarrollar en el Químico Farmacéutico las bases farmacológicas, técnicas y normativas para participar en la atención del paciente oncológico en Colombia: validar prescripciones, prevenir y manejar toxicidades, garantizar el manejo seguro de medicamentos peligrosos, gestionar el acceso y realizar farmacovigilancia. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta los tipos de NVIQ (aguda, tardía, anticipatoria, irruptiva) y la clasificación actualizada de riesgo emetógeno MASCC/ESMO.","Una pregunta que se usa para comprobar esta clase es: «¿Qué caracteriza a las náuseas y vómitos anticipatorios en el paciente con quimioterapia?» La respuesta correcta se apoya en lo siguiente: Las náuseas y vómitos inducidos por quimioterapia se clasifican en agudos (primeras 24 horas), tardíos (después de 24 horas), anticipatorios (antes del ciclo, condicionados por experiencias previas) e irruptivos (pese a la profilaxis). La mejor prevención de los anticipatorios es un buen control desde el primer ciclo. La fuente citada es: Clasificación MASCC/ESMO.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Tratamiento de soporte en el paciente oncológico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Confirmar la indicación. Verifica el problema de salud, el objetivo terapéutico y si el medicamento sigue siendo necesario. Evidencia que debe quedar: Problema de salud documentado.","Evaluar al paciente. Revisa edad, función renal y hepática, embarazo, comorbilidades y medicación concomitante. Evidencia que debe quedar: Perfil farmacoterapéutico.","Revisar seguridad e interacciones. Busca contraindicaciones, duplicidades, interacciones y riesgos de toxicidad. Evidencia que debe quedar: Lista de riesgos priorizada.","Ajustar y monitorizar. Propone dosis y parámetros de seguimiento, con frecuencia y umbral de acción. Evidencia que debe quedar: Plan de monitorización.","Educar y documentar. Explica el plan al paciente y registra la intervención, la respuesta y el seguimiento. Evidencia que debe quedar: Nota de seguimiento.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En una unidad de oncología, una encuesta muestra que el 40 % de los pacientes tiene dolor moderado o intenso (datos simulados). Muchos reciben solo tramadol, algunos no consiguen morfina por trámites de control especial y otros temen «volverse adictos». No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Error: validar solo la dosis y no la indicación Corrección: una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO»?","respuesta":"Interpreta los tipos de NVIQ (aguda, tardía, anticipatoria, irruptiva) y la clasificación actualizada de riesgo emetógeno MASCC/ESMO."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Tratamiento de soporte en el paciente oncológico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"Náuseas y Vómito en Quimioterapia","url":"https://www.youtube.com/watch?v=dDAGKDVyNvs"},{"cita":"[Página web] Emetic risk classification and evaluation of the emetogenicity of antineoplastic agents – updated MASCC/ESMO consensus recommendation (Jordan K et al., Support Care Cancer 2024). Supportive Care in Cancer (Springer) (EN)","url":"https://link.springer.com/article/10.1007/s00520-023-08220-5"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO"}],"keywords":["curso","farmacología","oncológica","fisiopatología","clasificación","emetogenicidad","mascc","unidad","tratamiento","soporte","paciente","oncológico"],"mapa":{"centro":"Fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 3. Tratamiento de soporte en el paciente oncológico","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Confirmar la indicación","Evaluar al paciente","Revisar seguridad e interacciones"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Problema de salud documentado","Perfil farmacoterapéutico","Lista de riesgos priorizada"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se razona una decisión farmacoterapéutica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Confirmar la indicación","detalle":"Verifica el problema de salud, el objetivo terapéutico y si el medicamento sigue siendo necesario.","icono":"Search","evidencia":"Problema de salud documentado"},{"titulo":"Evaluar al paciente","detalle":"Revisa edad, función renal y hepática, embarazo, comorbilidades y medicación concomitante.","icono":"ClipboardList","evidencia":"Perfil farmacoterapéutico"},{"titulo":"Revisar seguridad e interacciones","detalle":"Busca contraindicaciones, duplicidades, interacciones y riesgos de toxicidad.","icono":"Workflow","evidencia":"Lista de riesgos priorizada"},{"titulo":"Ajustar y monitorizar","detalle":"Propone dosis y parámetros de seguimiento, con frecuencia y umbral de acción.","icono":"FileCheck","evidencia":"Plan de monitorización"},{"titulo":"Educar y documentar","detalle":"Explica el plan al paciente y registra la intervención, la respuesta y el seguimiento.","icono":"RefreshCw","evidencia":"Nota de seguimiento"}]},"caso":{"titulo":"Fisiopatología de las NVIQ y clasificación de emetogenicidad MASCC/ESMO","contexto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, el equipo analiza este caso de unidad 3. Tratamiento de soporte en el paciente oncológico: una situación que exige documentar la decisión. La pregunta que decide esta clase es: ¿Qué caracteriza a las náuseas y vómitos anticipatorios en el paciente con quimioterapia?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Aparecen en las primeras 24 horas tras la quimioterapia y se controlan con antagonistas 5-HT3.","correcta":false,"retro":"Esa es la fase aguda."},{"texto":"Aparecen después del segundo día y duran hasta una semana tras cada ciclo.","correcta":false,"retro":"Esa es la fase tardía."},{"texto":"Aparecen pese a una profilaxis adecuada y requieren medicación de rescate.","correcta":false,"retro":"Ese es el vómito irruptivo."},{"texto":"Aparecen antes de la quimioterapia, condicionados por malas experiencias previas.","correcta":true,"retro":"Correcto. Se previenen con un buen control desde el primer ciclo."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 15. Antieméticos y esquemas de profilaxis según riesgo
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Antieméticos y esquemas de profilaxis según riesgo$t$
     AND m.title = $u$Unidad 3. Tratamiento de soporte en el paciente oncológico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Antieméticos y esquemas de profilaxis según riesgo$t$, $u$Unidad 3. Tratamiento de soporte en el paciente oncológico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Antieméticos y esquemas de profilaxis según riesgo","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un adulto mayor acumula medicamentos que ya no tienen indicación vigente. Lo que está en juego es el criterio de antieméticos y esquemas de profilaxis según riesgo. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar antieméticos y esquemas de profilaxis según riesgo con tus propias palabras y reconocer por qué importa en curso de Farmacología Oncológica.","Relacionar antieméticos y esquemas de profilaxis según riesgo con unidad 3. Tratamiento de soporte en el paciente oncológico y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar antieméticos y esquemas de profilaxis según riesgo y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Compara antagonistas 5-HT3, antagonistas NK1, corticoides y olanzapina, y su combinación según el riesgo emetógeno."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, antieméticos y esquemas de profilaxis según riesgo aparece en medio de una decisión que no admite improvisación: un adulto mayor acumula medicamentos que ya no tienen indicación vigente. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Tratamiento de soporte en el paciente oncológico. El objetivo del curso es claro: Desarrollar en el Químico Farmacéutico las bases farmacológicas, técnicas y normativas para participar en la atención del paciente oncológico en Colombia: validar prescripciones, prevenir y manejar toxicidades, garantizar el manejo seguro de medicamentos peligrosos, gestionar el acceso y realizar farmacovigilancia. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Compara antagonistas 5-HT3, antagonistas NK1, corticoides y olanzapina, y su combinación según el riesgo emetógeno.","Una pregunta que se usa para comprobar esta clase es: «Una paciente recibirá un esquema con cisplatino, de alto riesgo emetógeno. ¿Qué profilaxis antiemética corresponde según MASCC/ESMO?» La respuesta correcta se apoya en lo siguiente: Para la quimioterapia de alto riesgo emetógeno (como el cisplatino), MASCC/ESMO recomienda combinar un antagonista NK1, un antagonista 5-HT3, dexametasona y olanzapina, con cobertura de la fase tardía. La fuente citada es: Clasificación y recomendaciones MASCC/ESMO.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Tratamiento de soporte en el paciente oncológico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar antieméticos y esquemas de profilaxis según riesgo, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Confirmar la indicación. Verifica el problema de salud, el objetivo terapéutico y si el medicamento sigue siendo necesario. Evidencia que debe quedar: Problema de salud documentado.","Evaluar al paciente. Revisa edad, función renal y hepática, embarazo, comorbilidades y medicación concomitante. Evidencia que debe quedar: Perfil farmacoterapéutico.","Revisar seguridad e interacciones. Busca contraindicaciones, duplicidades, interacciones y riesgos de toxicidad. Evidencia que debe quedar: Lista de riesgos priorizada.","Ajustar y monitorizar. Propone dosis y parámetros de seguimiento, con frecuencia y umbral de acción. Evidencia que debe quedar: Plan de monitorización.","Educar y documentar. Explica el plan al paciente y registra la intervención, la respuesta y el seguimiento. Evidencia que debe quedar: Nota de seguimiento.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: ignorar la automedicación Corrección: los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento.","Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Error: monitorizar sin umbral de acción Corrección: pedir un examen sin saber qué se hará con el resultado no es seguimiento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar antieméticos y esquemas de profilaxis según riesgo en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Antieméticos y esquemas de profilaxis según riesgo»?","respuesta":"Compara antagonistas 5-HT3, antagonistas NK1, corticoides y olanzapina, y su combinación según el riesgo emetógeno."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Antieméticos y esquemas de profilaxis según riesgo se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Tratamiento de soporte en el paciente oncológico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"Náuseas y Vómito en Quimioterapia","url":"https://www.youtube.com/watch?v=dDAGKDVyNvs"},{"cita":"[Página web] MASCC/ESMO Antiemetic Guidelines 2023 – Highly emetogenic chemotherapy. Supportive Care in Cancer (Springer) (EN)","url":"https://link.springer.com/article/10.1007/s00520-023-08221-4"},{"cita":"Náuseas y vómitos inducidos por la quimioterapia (hoja informativa para pacientes). CancerCare (ES)","url":"https://media.cancercare.org/publications/original/115-fs_nausea_sp.pdf"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente antieméticos y esquemas de profilaxis según riesgo en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de antieméticos y esquemas de profilaxis según riesgo"}],"keywords":["curso","farmacología","oncológica","antieméticos","esquemas","profilaxis","según","riesgo","unidad","tratamiento","soporte","paciente"],"mapa":{"centro":"Antieméticos y esquemas de profilaxis según riesgo","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 3. Tratamiento de soporte en el paciente oncológico","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Confirmar la indicación","Evaluar al paciente","Revisar seguridad e interacciones"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Problema de salud documentado","Perfil farmacoterapéutico","Lista de riesgos priorizada"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se razona una decisión farmacoterapéutica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Confirmar la indicación","detalle":"Verifica el problema de salud, el objetivo terapéutico y si el medicamento sigue siendo necesario.","icono":"Search","evidencia":"Problema de salud documentado"},{"titulo":"Evaluar al paciente","detalle":"Revisa edad, función renal y hepática, embarazo, comorbilidades y medicación concomitante.","icono":"ClipboardList","evidencia":"Perfil farmacoterapéutico"},{"titulo":"Revisar seguridad e interacciones","detalle":"Busca contraindicaciones, duplicidades, interacciones y riesgos de toxicidad.","icono":"Workflow","evidencia":"Lista de riesgos priorizada"},{"titulo":"Ajustar y monitorizar","detalle":"Propone dosis y parámetros de seguimiento, con frecuencia y umbral de acción.","icono":"FileCheck","evidencia":"Plan de monitorización"},{"titulo":"Educar y documentar","detalle":"Explica el plan al paciente y registra la intervención, la respuesta y el seguimiento.","icono":"RefreshCw","evidencia":"Nota de seguimiento"}]},"caso":{"titulo":"Antieméticos y esquemas de profilaxis según riesgo","contexto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, el equipo analiza este caso de unidad 3. Tratamiento de soporte en el paciente oncológico: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Una paciente recibirá un esquema con cisplatino, de alto riesgo emetógeno. ¿Qué profilaxis antiemética corresponde según MASCC/ESMO?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Solo metoclopramida a necesidad, porque la profilaxis se reserva para los vómitos que ya aparecieron.","correcta":false,"retro":"Con riesgo alto la profilaxis es combinada y anticipada."},{"texto":"Solo dexametasona el día de la quimioterapia, que basta para cualquier nivel de riesgo.","correcta":false,"retro":"Con riesgo alto se combinan varios antieméticos."},{"texto":"Antagonista NK1, antagonista 5-HT3, dexametasona y olanzapina.","correcta":true,"retro":"Correcto. Es la combinación para el riesgo alto."},{"texto":"Un antagonista 5-HT3 solo, porque el cisplatino tiene un riesgo emetógeno bajo.","correcta":false,"retro":"El cisplatino es de riesgo alto."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 16. Neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares)
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares)$t$
     AND m.title = $u$Unidad 3. Tratamiento de soporte en el paciente oncológico$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares)$t$, $u$Unidad 3. Tratamiento de soporte en el paciente oncológico$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares)","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un paciente con enfermedad renal recibe una dosis que no fue ajustada. Lo que está en juego es el criterio de neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares). Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares) con tus propias palabras y reconocer por qué importa en curso de Farmacología Oncológica.","Relacionar neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares) con unidad 3. Tratamiento de soporte en el paciente oncológico y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares) y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe la neutropenia inducida por quimioterapia, los criterios de profilaxis primaria y secundaria con G-CSF y su seguimiento."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares) aparece en medio de una decisión que no admite improvisación: un paciente con enfermedad renal recibe una dosis que no fue ajustada. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 3. Tratamiento de soporte en el paciente oncológico. El objetivo del curso es claro: Desarrollar en el Químico Farmacéutico las bases farmacológicas, técnicas y normativas para participar en la atención del paciente oncológico en Colombia: validar prescripciones, prevenir y manejar toxicidades, garantizar el manejo seguro de medicamentos peligrosos, gestionar el acceso y realizar farmacovigilancia. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe la neutropenia inducida por quimioterapia, los criterios de profilaxis primaria y secundaria con G-CSF y su seguimiento.","Una pregunta que se usa para comprobar esta clase es: «Un paciente llama al día 10 de su ciclo de quimioterapia con fiebre de 38,5 °C y malestar. Dice que esperará a la cita de la semana siguiente. ¿Qué análisis es correcto?» La respuesta correcta se apoya en lo siguiente: La neutropenia febril (fiebre con neutrófilos muy bajos) suele aparecer entre los días 7 y 14 del ciclo y es una urgencia oncológica: requiere evaluación inmediata y antibióticos. Los factores estimulantes de colonias se usan como profilaxis primaria cuando el riesgo del esquema es alto o secundaria tras un episodio. La fuente citada es: Fichas técnicas de filgrastim y pegfilgrastim; recomendaciones de neutropenia febril.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 3. Tratamiento de soporte en el paciente oncológico y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares), sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Confirmar la indicación. Verifica el problema de salud, el objetivo terapéutico y si el medicamento sigue siendo necesario. Evidencia que debe quedar: Problema de salud documentado.","Evaluar al paciente. Revisa edad, función renal y hepática, embarazo, comorbilidades y medicación concomitante. Evidencia que debe quedar: Perfil farmacoterapéutico.","Revisar seguridad e interacciones. Busca contraindicaciones, duplicidades, interacciones y riesgos de toxicidad. Evidencia que debe quedar: Lista de riesgos priorizada.","Ajustar y monitorizar. Propone dosis y parámetros de seguimiento, con frecuencia y umbral de acción. Evidencia que debe quedar: Plan de monitorización.","Educar y documentar. Explica el plan al paciente y registra la intervención, la respuesta y el seguimiento. Evidencia que debe quedar: Nota de seguimiento.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En una unidad de oncología, una encuesta muestra que el 40 % de los pacientes tiene dolor moderado o intenso (datos simulados). Muchos reciben solo tramadol, algunos no consiguen morfina por trámites de control especial y otros temen «volverse adictos». No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Error: ignorar la automedicación Corrección: los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento.","Error: validar solo la dosis y no la indicación Corrección: una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares) en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares)»?","respuesta":"Describe la neutropenia inducida por quimioterapia, los criterios de profilaxis primaria y secundaria con G-CSF y su seguimiento."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"El registro de los pasos del proceso, la fuente consultada y la decisión documentada con su justificación."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares) se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 3. Tratamiento de soporte en el paciente oncológico.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"Neutropenia: During and After Cancer Treatment","url":"https://www.youtube.com/watch?v=H16yIhTbh8c"},{"cita":"[Página web] MASCC Guidelines – índice de guías de soporte (antieméticos, mucositis, neutropenia). MASCC (EN)","url":"https://mascc.org/resources/mascc-guidelines/"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares) en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares)"}],"keywords":["curso","farmacología","oncológica","neutropenia","febril","factores","estimulantes","colonias","filgrastim","pegfilgrastim","biosimilares","unidad"],"mapa":{"centro":"Neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares)","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 3. Tratamiento de soporte en el paciente oncológico","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Confirmar la indicación","Evaluar al paciente","Revisar seguridad e interacciones"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Problema de salud documentado","Perfil farmacoterapéutico","Lista de riesgos priorizada"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se razona una decisión farmacoterapéutica","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Confirmar la indicación","detalle":"Verifica el problema de salud, el objetivo terapéutico y si el medicamento sigue siendo necesario.","icono":"Search","evidencia":"Problema de salud documentado"},{"titulo":"Evaluar al paciente","detalle":"Revisa edad, función renal y hepática, embarazo, comorbilidades y medicación concomitante.","icono":"ClipboardList","evidencia":"Perfil farmacoterapéutico"},{"titulo":"Revisar seguridad e interacciones","detalle":"Busca contraindicaciones, duplicidades, interacciones y riesgos de toxicidad.","icono":"Workflow","evidencia":"Lista de riesgos priorizada"},{"titulo":"Ajustar y monitorizar","detalle":"Propone dosis y parámetros de seguimiento, con frecuencia y umbral de acción.","icono":"FileCheck","evidencia":"Plan de monitorización"},{"titulo":"Educar y documentar","detalle":"Explica el plan al paciente y registra la intervención, la respuesta y el seguimiento.","icono":"RefreshCw","evidencia":"Nota de seguimiento"}]},"caso":{"titulo":"Neutropenia febril y factores estimulantes de colonias (filgrastim, pegfilgrastim, biosimilares)","contexto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, el equipo analiza este caso de unidad 3. Tratamiento de soporte en el paciente oncológico: una situación que exige documentar la decisión. La pregunta que decide esta clase es: Un paciente llama al día 10 de su ciclo de quimioterapia con fiebre de 38,5 °C y malestar. Dice que esperará a la cita de la semana siguiente. ¿Qué análisis es correcto?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Puede esperar, porque la fiebre durante la quimioterapia es un efecto esperado sin importancia.","correcta":false,"retro":"Puede ser una neutropenia febril."},{"texto":"Puede ser una neutropenia febril, una urgencia: debe consultar de inmediato.","correcta":true,"retro":"Correcto. Requiere evaluación y antibióticos sin demora."},{"texto":"Basta con tomar acetaminofén y medir la fiebre cada día hasta la próxima cita.","correcta":false,"retro":"Enmascarar la fiebre retrasa una urgencia."},{"texto":"Debe suspender la quimioterapia por su cuenta y reiniciarla cuando se le pase la fiebre.","correcta":false,"retro":"La conducta es consultar de inmediato."}]}}$j$::jsonb;
