  -- 03. Clasificación de los citotóxicos y mapa de toxicidades
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Clasificación de los citotóxicos y mapa de toxicidades$t$
     AND m.title = $u$Unidad 1. Fundamentos de la quimioterapia citotóxica y agentes alquilantes$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Clasificación de los citotóxicos y mapa de toxicidades$t$, $u$Unidad 1. Fundamentos de la quimioterapia citotóxica y agentes alquilantes$u$;
