  -- 05. Platinos: cisplatino, carboplatino y oxaliplatino
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Platinos: cisplatino, carboplatino y oxaliplatino$t$
     AND m.title = $u$Unidad 1. Fundamentos de la quimioterapia citotóxica y agentes alquilantes$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
