  -- 18. Alcaloides de la vinca y el error fatal de la vincristina intratecal
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Alcaloides de la vinca y el error fatal de la vincristina intratecal$t$
     AND m.title = $u$Unidad 3. Antraciclinas, inhibidores de topoisomerasa y antimicrotúbulos$u$
   ORDER BY l.id LIMIT 1;
