  -- 11. MSI-H/dMMR, TMB e indicaciones principales por tumor
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$MSI-H/dMMR, TMB e indicaciones principales por tumor$t$
