    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$CAR-T: estructura, proceso e indicaciones$t$
     AND m.title = $u$Unidad 4. Terapias celulares, biespecíficos, vacunas y patrones de respuesta$u$
   ORDER BY l.id LIMIT 1;
