    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 26. Caso: síndrome de liberación de citoquinas tras CAR-T
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: síndrome de liberación de citoquinas tras CAR-T$t$
     AND m.title = $u$Unidad 4. Terapias celulares, biespecíficos, vacunas y patrones de respuesta$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: síndrome de liberación de citoquinas tras CAR-T$t$, $u$Unidad 4. Terapias celulares, biespecíficos, vacunas y patrones de respuesta$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso: síndrome de liberación de citoquinas tras CAR-T","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, un paciente con enfermedad renal recibe una dosis que no fue ajustada. Lo que está en juego es el criterio de caso: síndrome de liberación de citoquinas tras CAR-T. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso: síndrome de liberación de citoquinas tras CAR-T con tus propias palabras y reconocer por qué importa en curso de Inmunoterapia Oncológica.","Relacionar caso: síndrome de liberación de citoquinas tras CAR-T con unidad 4. Terapias celulares, biespecíficos, vacunas y patrones de respuesta y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso: síndrome de liberación de citoquinas tras CAR-T y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"El QF participa en el manejo de un SLC grado 2 y en la prevención de ICANS, asegurando rescates, profilaxis y farmacovigilancia. ejecutar el abordaje farmacéutico de un síndrome de liberación de citoquinas (SLC) e ICANS en un paciente que recibe terapia CAR-T. Caso: mujer de 45 años con linfoma B difuso de células grandes refractario a dos líneas, que recibe CAR-T anti-CD19 tras linfodepleción con fludarabina y ciclofosfamida. En el día +3 presenta fiebre de 39,2 °C,…"},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, caso: síndrome de liberación de citoquinas tras CAR-T aparece en medio de una decisión que no admite improvisación: un paciente con enfermedad renal recibe una dosis que no fue ajustada. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Terapias celulares, biespecíficos, vacunas y patrones de respuesta. El objetivo del curso es claro: Desarrollar en el químico farmacéutico las competencias para validar, preparar, dispensar y hacer seguimiento farmacoterapéutico seguro y costo-efectivo de la inmunoterapia oncológica, incluyendo la detección, graduación y manejo de eventos adversos inmunorrelacionados y la gestión del acceso en el sistema de salud colombiano. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: El QF participa en el manejo de un SLC grado 2 y en la prevención de ICANS, asegurando rescates, profilaxis y farmacovigilancia. ejecutar el abordaje farmacéutico de un síndrome de liberación de citoquinas (SLC) e ICANS en un paciente que recibe terapia CAR-T. Caso: mujer de 45 años con linfoma B difuso de células grandes refractario a dos líneas, que recibe CAR-T anti-CD19 tras linfodepleción con fludarabina y ciclofosfamida. En el día +3 presenta fiebre de 39,2 °C,…","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en indicación y en problema relacionado con medicamentos, no en la intuición.","La clase pertenece a unidad 4. Terapias celulares, biespecíficos, vacunas y patrones de respuesta y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de apoyo al manejo del síndrome de liberación de citoquinas.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso: síndrome de liberación de citoquinas tras CAR-T, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Gradúa el síndrome de liberación de citoquinas con los criterios ASTCT y justifica. Evidencia que debe quedar: Registro del paso.","Describe el tratamiento indicado según el grado y la ficha técnica (tocilizumab, corticoides). Evidencia que debe quedar: Registro del paso.","Verifica la disponibilidad y la preparación del tocilizumab. Evidencia que debe quedar: Registro del paso.","Explica cómo se vigila el ICANS (puntuación ICE) y qué medicamento se prefiere si aparece. Evidencia que debe quedar: Registro del paso.","Define la farmacovigilancia del evento. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: Un hospital universitario planea iniciar terapia CAR-T y anticuerpos biespecíficos (datos simulados). El servicio farmacéutico nunca ha manejado productos celulares, no tiene protocolo de síndrome de liberación de citoquinas y el inventario de tocilizumab es irregular. No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Error: monitorizar sin umbral de acción Corrección: pedir un examen sin saber qué se hará con el resultado no es seguimiento.","Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso: síndrome de liberación de citoquinas tras CAR-T en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso: síndrome de liberación de citoquinas tras CAR-T»?","respuesta":"El QF participa en el manejo de un SLC grado 2 y en la prevención de ICANS, asegurando rescates, profilaxis y farmacovigilancia. ejecutar el abordaje farmacéutico de un síndrome de liberación de citoquinas (SLC) e ICANS en un paciente que recibe terapia CAR-T. Caso: mujer de 45 años con linfoma B difuso de células grandes refractario a dos líneas, que recibe CAR-T anti-CD19 tras linfodepleción con fludarabina y ciclofosfamida. En el día +3 presenta fiebre de 39,2 °C,…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de apoyo al manejo del síndrome de liberación de citoquinas.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Caso: síndrome de liberación de citoquinas tras CAR-T se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Terapias celulares, biespecíficos, vacunas y patrones de respuesta.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"Efecto secundario de la terapia de células CAR-T (Dr. Aaron Goodman). CancerGRACE (ES)","url":"https://cancergrace.org/sites/default/files/2023-04/Efecto%20secundario%20de%20la%20terapia%20de%20ce%CC%81lulas%20CAR-T%20-%20Goodman.pdf"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso: síndrome de liberación de citoquinas tras CAR-T en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de caso: síndrome de liberación de citoquinas tras CAR-T"}],"keywords":["curso","inmunoterapia","oncológica","síndrome","liberación","citoquinas","unidad","terapias","celulares","biespecíficos","vacunas","patrones"],"mapa":{"centro":"Caso: síndrome de liberación de citoquinas tras CAR-T","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 4. Terapias celulares, biespecíficos, vacunas y patrones de respuesta","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se aplica: Síndrome de liberación de citoquinas tras CAR-T","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Gradúa el síndrome de liberación de citoquinas con los criterios ASTCT y justifica.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Describe el tratamiento indicado según el grado y la ficha técnica (tocilizumab, corticoides).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Verifica la disponibilidad y la preparación del tocilizumab.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Explica cómo se vigila el ICANS (puntuación ICE) y qué medicamento se prefiere si aparece.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Define la farmacovigilancia del evento.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Síndrome de liberación de citoquinas tras CAR-T","contexto":"Doña Patricia tiene 45 años y un linfoma B difuso de células grandes refractario (datos simulados). Recibió CAR-T anti-CD19 tras linfodepleción con fludarabina y ciclofosfamida. En el día +3 tiene fiebre de 39,2 °C, frecuencia de 118 lpm y presión de 85/50 mmHg que responde a un bolo de cristaloides, con saturación normal. Está orientada. El hematólogo pide al servicio farmacéutico apoyo con el manejo.","pregunta":"¿Qué decisión demuestra que entendiste caso: síndrome de liberación de citoquinas tras CAR-T?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
