  -- 29. Preparación y administración de anticuerpos monoclonales y biespecíficos
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Preparación y administración de anticuerpos monoclonales y biespecíficos$t$
     AND m.title = $u$Unidad 5. Rol del químico farmacéutico y acceso en Colombia$u$
