      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 05. Caso: paciente con CPCNP sin perfil molecular completo
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: paciente con CPCNP sin perfil molecular completo$t$
     AND m.title = $u$Unidad 1. Medicina de precisión y biomarcadores en oncología$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: paciente con CPCNP sin perfil molecular completo$t$, $u$Unidad 1. Medicina de precisión y biomarcadores en oncología$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso: paciente con CPCNP sin perfil molecular completo","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, el paciente abandona el tratamiento y nadie lo detecta hasta la siguiente consulta. Lo que está en juego es el criterio de caso: paciente con CPCNP sin perfil molecular completo. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso: paciente con CPCNP sin perfil molecular completo con tus propias palabras y reconocer por qué importa en curso de Terapias Dirigidas en Oncología.","Relacionar caso: paciente con CPCNP sin perfil molecular completo con unidad 1. Medicina de precisión y biomarcadores en oncología y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso: paciente con CPCNP sin perfil molecular completo y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Caso de adenocarcinoma de pulmón avanzado en el que el QF identifica la falta de pruebas de EGFR, ALK, ROS1, BRAF y PD-L1 antes de iniciar el tratamiento, y propone la ruta de solicitud."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, caso: paciente con CPCNP sin perfil molecular completo aparece en medio de una decisión que no admite improvisación: el paciente abandona el tratamiento y nadie lo detecta hasta la siguiente consulta. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Medicina de precisión y biomarcadores en oncología. El objetivo del curso es claro: Que el QF comprenda el mecanismo, las indicaciones basadas en biomarcadores, la farmacocinética, las toxicidades y las interacciones de las principales terapias dirigidas en oncología, y que aplique intervenciones de seguimiento farmacoterapéutico, farmacovigilancia y gestión del acceso en el contexto colombiano. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Caso de adenocarcinoma de pulmón avanzado en el que el QF identifica la falta de pruebas de EGFR, ALK, ROS1, BRAF y PD-L1 antes de iniciar el tratamiento, y propone la ruta de solicitud.","Una pregunta que se usa para comprobar esta clase es: «A un paciente con adenocarcinoma de pulmón avanzado, en buen estado general, le prescriben quimioinmunoterapia sin resultados de EGFR, ALK ni ROS1. ¿Cuál es la mejor valoración del QF?» La respuesta correcta se apoya en lo siguiente: En el adenocarcinoma de pulmón avanzado se recomienda conocer el perfil molecular (EGFR, ALK, ROS1, BRAF, entre otros) y el PD-L1 antes de iniciar la primera línea: una alteración dirigible cambia el tratamiento y la inmunoterapia previa puede aumentar la toxicidad de algunos ITK. El QF identifica la falta y gestiona la ruta de solicitud. La fuente citada es: Fichas técnicas de osimertinib y de los ITK de ALK.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Medicina de precisión y biomarcadores en oncología y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe con propuesta de ruta molecular y comunicación al oncólogo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso: paciente con CPCNP sin perfil molecular completo, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Identifica los biomarcadores que faltan y explica por qué su perfil clínico hace probable una alteración dirigible. Evidencia que debe quedar: Registro del paso.","Explica qué cambiaría si se encontrara una mutación de EGFR (incluida la actividad en el SNC). Evidencia que debe quedar: Registro del paso.","Propone la ruta para obtener el perfil (panel de secuenciación, biopsia líquida) y cómo acelerar la autorización. Evidencia que debe quedar: Registro del paso.","Analiza los riesgos de iniciar la inmunoterapia antes del resultado. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al oncólogo. Evidencia que debe quedar: Registro del paso.","Revisa con la rúbrica y sube tu informe en PDF o DOCX. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: dar por hecha la adherencia Corrección: la adherencia se verifica con registros de dispensación y conversación, no se supone.","Error: ignorar la automedicación Corrección: los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento.","Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso: paciente con CPCNP sin perfil molecular completo en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso: paciente con CPCNP sin perfil molecular completo»?","respuesta":"Caso de adenocarcinoma de pulmón avanzado en el que el QF identifica la falta de pruebas de EGFR, ALK, ROS1, BRAF y PD-L1 antes de iniciar el tratamiento, y propone la ruta de solicitud."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe con propuesta de ruta molecular y comunicación al oncólogo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Caso: paciente con CPCNP sin perfil molecular completo se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Medicina de precisión y biomarcadores en oncología.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"Terapia personalizada en cáncer de pulmón: EGFR, ALK, ROS1, BRAF – Dr. Hugo Castro, oncólogo","url":"https://www.youtube.com/watch?v=VEbVimYrZgo"},{"cita":"[Página web] Pruebas de biomarcadores para el tratamiento de cáncer. Instituto Nacional del Cáncer (NCI, EE. UU.) (ES)","url":"https://www.cancer.gov/espanol/cancer/tratamiento/tipos/pruebas-de-biomarcadores-tratamiento-cancer"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso: paciente con CPCNP sin perfil molecular completo en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de caso: paciente con CPCNP sin perfil molecular completo"}],"keywords":["curso","terapias","dirigidas","oncología","paciente","cpcnp","perfil","molecular","completo","unidad","medicina","precisión"],"mapa":{"centro":"Caso: paciente con CPCNP sin perfil molecular completo","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 1. Medicina de precisión y biomarcadores en oncología","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se aplica: Cáncer de pulmón sin perfil molecular completo","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Identifica los biomarcadores que faltan y explica por qué su perfil clínico hace probable una alteración dirigible.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Explica qué cambiaría si se encontrara una mutación de EGFR (incluida la actividad en el SNC).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Propone la ruta para obtener el perfil (panel de secuenciación, biopsia líquida) y cómo acelerar la autorización.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Analiza los riesgos de iniciar la inmunoterapia antes del resultado.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Redacta la comunicación al oncólogo.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Revisa con la rúbrica y sube tu informe en PDF o DOCX.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Caso: paciente con CPCNP sin perfil molecular completo","contexto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, el equipo analiza este caso de unidad 1. Medicina de precisión y biomarcadores en oncología: Don Gilberto tiene 61 años, nunca fumó y tiene un adenocarcinoma de pulmón estadio IV con metástasis cerebrales pequeñas, ECOG 1 (datos simulados). Le prescriben quimioterapia con pembrolizumab. En la historia solo aparece el PD-L1 (TPS 20 %); no hay resultados de EGFR, ALK, ROS1 ni BRAF. La biopsia fue pequeña. Su EPS tarda tres semanas en autorizar las pruebas. La pregunta que decide esta clase es: A un paciente con adenocarcinoma de pulmón avanzado, en buen estado general, le prescriben quimioinmunoterapia sin resultados de EGFR, ALK ni ROS1. ¿Cuál es la mejor valoración del QF?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Es adecuada, porque el perfil molecular no cambia el tratamiento del adenocarcinoma de pulmón.","correcta":false,"retro":"El perfil molecular puede cambiar el tratamiento por completo."},{"texto":"Conviene comunicar al oncólogo la falta del perfil molecular y gestionarlo, porque una alteración cambia la primera línea.","correcta":true,"retro":"Correcto. Salvo urgencia clínica, se espera el resultado."},{"texto":"Es adecuada si se agrega un inhibidor de EGFR a la quimioinmunoterapia por si acaso.","correcta":false,"retro":"Añadir un ITK sin biomarcador no es adecuado."},{"texto":"Conviene suspender cualquier tratamiento hasta repetir la biopsia en seis meses.","correcta":false,"retro":"Un retraso tan largo no es aceptable."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
