  -- 07. Trastuzumab y pertuzumab: bloqueo dual de HER2 y cardiotoxicidad
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Trastuzumab y pertuzumab: bloqueo dual de HER2 y cardiotoxicidad$t$
     AND m.title = $u$Unidad 2. Anticuerpos monoclonales dirigidos y conjugados anticuerpo-fármaco$u$
   ORDER BY l.id LIMIT 1;
