  -- 10. Rituximab: anti-CD20, reacciones a la infusión y reactivación de hepatitis B
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Rituximab: anti-CD20, reacciones a la infusión y reactivación de hepatitis B$t$
     AND m.title = $u$Unidad 2. Anticuerpos monoclonales dirigidos y conjugados anticuerpo-fármaco$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
