    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 29. Caso: progresión con osimertinib y uso de la biopsia líquida
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Caso: progresión con osimertinib y uso de la biopsia líquida$t$
     AND m.title = $u$Unidad 4. Seguridad: toxicidades, interacciones, adherencia y resistencia$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Caso: progresión con osimertinib y uso de la biopsia líquida$t$, $u$Unidad 4. Seguridad: toxicidades, interacciones, adherencia y resistencia$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Caso: progresión con osimertinib y uso de la biopsia líquida","texto":"En un servicio farmacéutico hospitalario o ambulatorio en Colombia, una interacción entre dos medicamentos explica por qué el tratamiento no funciona. Lo que está en juego es el criterio de caso: progresión con osimertinib y uso de la biopsia líquida. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar caso: progresión con osimertinib y uso de la biopsia líquida con tus propias palabras y reconocer por qué importa en curso de Terapias Dirigidas en Oncología.","Relacionar caso: progresión con osimertinib y uso de la biopsia líquida con unidad 4. Seguridad: toxicidades, interacciones, adherencia y resistencia y con las decisiones de el químico farmacéutico clínico.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar caso: progresión con osimertinib y uso de la biopsia líquida y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Caso en el que el QF apoya la reevaluación molecular al progresar y documenta la adherencia y las interacciones para orientar la siguiente línea."},{"icono":"ShieldCheck","termino":"Indicación","definicion":"La razón clínica por la que se usa un medicamento en un paciente concreto. Sin indicación vigente, cualquier uso es un problema de necesidad."},{"icono":"FileCheck","termino":"Problema relacionado con medicamentos","definicion":"Una situación de necesidad, efectividad o seguridad que impide o dificulta lograr el resultado terapéutico esperado."},{"icono":"Network","termino":"Interacción","definicion":"La modificación del efecto de un medicamento por otro, por un alimento o por una condición del paciente. Debe evaluarse antes de dispensar."},{"icono":"ClipboardCheck","termino":"Monitorización","definicion":"El seguimiento de parámetros clínicos o de laboratorio para confirmar efectividad y detectar toxicidad a tiempo."},{"icono":"RefreshCw","termino":"Ajuste de dosis","definicion":"La modificación de la dosis según función renal, hepática, edad, peso u otros factores que cambian la exposición al medicamento."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En un servicio farmacéutico hospitalario o ambulatorio en Colombia, caso: progresión con osimertinib y uso de la biopsia líquida aparece en medio de una decisión que no admite improvisación: una interacción entre dos medicamentos explica por qué el tratamiento no funciona. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 4. Seguridad: toxicidades, interacciones, adherencia y resistencia. El objetivo del curso es claro: Que el QF comprenda el mecanismo, las indicaciones basadas en biomarcadores, la farmacocinética, las toxicidades y las interacciones de las principales terapias dirigidas en oncología, y que aplique intervenciones de seguimiento farmacoterapéutico, farmacovigilancia y gestión del acceso en el contexto colombiano. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Caso en el que el QF apoya la reevaluación molecular al progresar y documenta la adherencia y las interacciones para orientar la siguiente línea.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en indicación y en problema relacionado con medicamentos, no en la intuición.","La clase pertenece a unidad 4. Seguridad: toxicidades, interacciones, adherencia y resistencia y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe de análisis con comunicación al hematólogo.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar caso: progresión con osimertinib y uso de la biopsia líquida, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Estima la adherencia con los registros de dispensación. Evidencia que debe quedar: Registro del paso.","Analiza la interacción del omeprazol con el dasatinib y cómo resolverla. Evidencia que debe quedar: Registro del paso.","Analiza el hipérico y su efecto sobre el dasatinib. Evidencia que debe quedar: Registro del paso.","Propone un plan de adherencia adaptado a sus turnos. Evidencia que debe quedar: Registro del paso.","Explica cuándo estaría indicada la búsqueda de mutaciones de resistencia. Evidencia que debe quedar: Registro del paso.","Redacta la comunicación al hematólogo. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: no ajustar por función renal Corrección: la misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal.","Error: validar solo la dosis y no la indicación Corrección: una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad.","Error: ignorar la automedicación Corrección: los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar caso: progresión con osimertinib y uso de la biopsia líquida en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"]}],"errores":[{"error":"Validar solo la dosis y no la indicación","correccion":"Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."},{"error":"Ignorar la automedicación","correccion":"Los AINE, los antiácidos y los suplementos pueden cambiar el efecto o la seguridad del tratamiento."},{"error":"No ajustar por función renal","correccion":"La misma dosis no sirve para todos los pacientes; la eliminación cambia con la función renal."},{"error":"Monitorizar sin umbral de acción","correccion":"Pedir un examen sin saber qué se hará con el resultado no es seguimiento."},{"error":"Dar por hecha la adherencia","correccion":"La adherencia se verifica con registros de dispensación y conversación, no se supone."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Caso: progresión con osimertinib y uso de la biopsia líquida»?","respuesta":"Caso en el que el QF apoya la reevaluación molecular al progresar y documenta la adherencia y las interacciones para orientar la siguiente línea."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe de análisis con comunicación al hematólogo.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Validar solo la dosis y no la indicación Una dosis correcta de un medicamento innecesario sigue siendo un problema de necesidad."}],"resumen":["Caso: progresión con osimertinib y uso de la biopsia líquida se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 4. Seguridad: toxicidades, interacciones, adherencia y resistencia.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué parámetro monitorizarías y en qué plazo para saber si la decisión funcionó?"],"referencias":[{"cita":"Terapia dirigida en el cáncer de pulmón de células no pequeñas","url":"https://www.youtube.com/watch?v=WyYFrFbonS8"},{"cita":"[Página web] La biopsia líquida en el manejo del cáncer: una nueva herramienta revolucionaria de la medicina de precisión, aún con limitaciones. PubMed Central (artículo de revisión) (ES)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10197306"},{"cita":"INVIMA. Consulta de medicamentos y fichas técnicas aprobadas.","url":"https://www.invima.gov.co/"},{"cita":"Organización Mundial de la Salud. Seguridad del paciente y uso racional de medicamentos.","url":"https://www.who.int/es/health-topics/patient-safety"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1403 de 2007, servicio farmacéutico.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/RESOLUCI%C3%93N%201403%20DE%202007.pdf"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente caso: progresión con osimertinib y uso de la biopsia líquida en un servicio farmacéutico hospitalario o ambulatorio en Colombia.","alt":"Ilustración de caso: progresión con osimertinib y uso de la biopsia líquida"}],"keywords":["curso","terapias","dirigidas","oncología","progresión","osimertinib","biopsia","líquida","unidad","seguridad","toxicidades","interacciones"],"mapa":{"centro":"Caso: progresión con osimertinib y uso de la biopsia líquida","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Farmacología","Unidad 4. Seguridad: toxicidades, interacciones, adherencia y resistencia","Indicación"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Validar solo la dosis y no la indicación","Ignorar la automedicación","No ajustar por función renal"]}]},"proceso":{"titulo":"Cómo se aplica: Pérdida de respuesta a un ITK: causas farmacológicas","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Estima la adherencia con los registros de dispensación.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Analiza la interacción del omeprazol con el dasatinib y cómo resolverla.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Analiza el hipérico y su efecto sobre el dasatinib.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Propone un plan de adherencia adaptado a sus turnos.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Explica cuándo estaría indicada la búsqueda de mutaciones de resistencia.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Redacta la comunicación al hematólogo.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Pérdida de respuesta a un ITK: causas farmacológicas","contexto":"Don Fabio tiene 54 años y leucemia mieloide crónica tratada con dasatinib (datos simulados). Tenía respuesta molecular mayor y en el último control la perdió. Toma omeprazol 40 mg en la mañana junto con el dasatinib, usa hipérico «para el ánimo» desde hace tres meses y sus retiros en la farmacia son cada 45 días aunque se le entrega para 30. Trabaja en turnos rotativos y dice que «a veces no se acuerda».","pregunta":"¿Qué decisión demuestra que entendiste caso: progresión con osimertinib y uso de la biopsia líquida?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
